using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Uri baseAddress;

    private string? method, path, contentType, body;

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        baseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add(baseAddress + "");
        listener.Start();
        client = new HttpClient { BaseAddress = baseAddress };
    }

    private Task Provider(int status, string responseBody, string contentTypeHeader = "application/json") =>
        Task.Run(async () =>
        {
            var context = await listener.GetContextAsync();
            method = context.Request.HttpMethod;
            path = context.Request.Url!.AbsolutePath;
            contentType = context.Request.ContentType;
            using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
                body = await reader.ReadToEndAsync();

            var bytes = Encoding.UTF8.GetBytes(responseBody);
            context.Response.StatusCode = status;
            context.Response.ContentType = contentTypeHeader;
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        });

    private async Task<AuthorizationOutcome> Authorize(Task provider)
    {
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);
        await provider;
        return outcome;
    }

    [Fact]
    public async Task Sends_a_JSON_POST_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        await Authorize(Provider(200, """{"status":"approved"}"""));

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        using var json = JsonDocument.Parse(body!);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Assert.Equal(AuthorizationOutcome.Approved, await Authorize(Provider(200, """{"status":"approved"}""")));
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(Provider(200, """{"status":"declined"}""")));
    }

    [Fact]
    public async Task Unknown_fields_in_the_answer_are_ignored()
    {
        Assert.Equal(AuthorizationOutcome.Approved,
            await Authorize(Provider(200, """{"id":"a1","status":"approved","extra":{"x":1}}""")));
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_decline_not_an_error()
    {
        Assert.Equal(AuthorizationOutcome.Declined,
            await Authorize(Provider(402, """{"error":"card_refused"}""")));
    }

    [Fact]
    public async Task An_answer_without_a_status_is_never_treated_as_approved()
    {
        Assert.Equal(AuthorizationOutcome.Declined, await Authorize(Provider(200, "{}")));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_surface_as_failures_instead_of_a_decision(int status)
    {
        var provider = Provider(status, """{"status":"approved"}""");

        var ex = await Assert.ThrowsAsync<HttpRequestException>(() => Authorize(provider));

        Assert.Equal((HttpStatusCode)status, ex.StatusCode);
    }

    [Fact]
    public async Task A_malformed_answer_surfaces_as_a_failure()
    {
        var provider = Provider(200, "not json");

        await Assert.ThrowsAnyAsync<JsonException>(() => Authorize(provider));
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
